171	$insideListHandler = static function (
172	        Request $req,
173	        int $boardNo,
174	        string $viewName,
175	        string $listRouteName
176	    ) use ($resolvePositiveInt): string {
177	        $page = $resolvePositiveInt($req->query('page', 1), 1);
178	        $categoryRaw = $req->query('category');
179	        $categoryNo = null;
180	        if ($categoryRaw !== null && $categoryRaw !== '') {
181	            $cv = filter_var($categoryRaw, FILTER_VALIDATE_INT);
182	            if ($cv !== false && (int) $cv > 0) {
183	                $categoryNo = (int) $cv;
184	            }
185	        }
186	        $q = trim((string) $req->query('q', ''));
187	        $list = inside_board_list(
188	            $boardNo,
189	            $page,
190	            $categoryNo,
191	            $q !== '' ? $q : null
192	        );
193	
194	        $listUrl = route($listRouteName, [], false);
195	        $mergeQuery = static function (array $extra) use ($q): array {
196	            $p = $extra;
197	            if ($q !== '') {
198	                $p['q'] = $q;
199	            }
200	
201	            return array_filter(
202	                $p,
203	                static fn ($v) => $v !== null && $v !== ''
204	            );
205	        };
206	
207	        $categoryItems = [];
208	        $manage = inside_board_manage($boardNo);
209	        $catEnabled = ($manage['category_yn'] ?? 'N') === 'Y';
210	        $allQuery = $mergeQuery([]);
211	        $categoryItems[] = [
212	            'label' => 'ALL',
213	            'href' => $listUrl . ($allQuery !== [] ? '?' . http_build_query($allQuery) : ''),
214	            'active' => $categoryNo === null,
215	        ];
216	        if ($catEnabled) {
217	            foreach (inside_board_categories($boardNo) as $row) {
218	                $cn = (int) ($row['no'] ?? 0);
219	                if ($cn < 1) {
220	                    continue;
221	                }
222	                $cq = $mergeQuery(['category' => $cn]);
223	                $categoryItems[] = [
224	                    'label' => (string) ($row['name'] ?? ''),
225	                    'href' => $listUrl . '?' . http_build_query($cq),
226	                    'active' => $categoryNo === $cn,
227	                ];
228	            }
229	        }
230	
231	        $paginationQuery = $mergeQuery([]);
232	
233	        return render($viewName, [
234	            'pageType' => 'inside',
235	            'boardNo' => $boardNo,
236	            'posts' => $list['rows'],
237	            'paginationTotal' => $list['totalPages'],
238	            'paginationCurrent' => $list['page'],
239	            'paginationQueryParams' => $paginationQuery,
240	            'categoryItems' => $categoryItems,
241	            'searchQuery' => $q,
242	            'listRouteName' => $listRouteName,
243	            'activeCategoryNo' => $categoryNo,
244	        ]);
245	};
