247	$insideViewHandler = static function (string $no, int $boardNo, string $viewName, string $listRouteName, string $viewRouteName) {
248	        $postNo = filter_var($no, FILTER_VALIDATE_INT);
249	        if ($postNo === false || $postNo < 1) {
250	            return response(render('errors.404'), 404);
251	        }
252	
253	        $post = inside_board_find((int) $postNo, $boardNo);
254	        if ($post === null) {
255	            return response(render('errors.404'), 404);
256	        }
257	
258	        $neighbors = inside_board_neighbors((int) $postNo, $boardNo);
259	        $listUrl = route($listRouteName, [], false);
260	
261	        $prevUrl = null;
262	        $prevTitle = '';
263	        if ($neighbors['prev'] !== null) {
264	            $prevUrl = route($viewRouteName, ['no' => (string) ($neighbors['prev']['no'] ?? '')], false);
265	            $prevTitle = (string) ($neighbors['prev']['title'] ?? '');
266	        }
267	
268	        $nextUrl = null;
269	        $nextTitle = '';
270	        if ($neighbors['next'] !== null) {
271	            $nextUrl = route($viewRouteName, ['no' => (string) ($neighbors['next']['no'] ?? '')], false);
272	            $nextTitle = (string) ($neighbors['next']['title'] ?? '');
273	        }
274	
275	        return render($viewName, [
276	            'pageType' => 'inside',
277	            'boardNo' => $boardNo,
278	            'post' => $post,
279	            'listUrl' => $listUrl,
280	            'prevUrl' => $prevUrl,
281	            'prevTitle' => $prevTitle,
282	            'nextUrl' => $nextUrl,
283	            'nextTitle' => $nextTitle,
284	        ]);
285	};
